class Solution {
public:
    bool validPath(int n, vector<vector<int>>& edges, int source, int destination) {
        if(source == destination) return true;
        vector<int> father(n);
        for(int i = 0; i < n; i++) father[i] = i;
        int size = edges.size();
        for(int i = 0; i < size ; i ++){
            int u = edges[i][0], v = edges[i][1];
            int father_u = father[u], father_v = father[v];
            while(father_u != father[father_u]) father_u = father[father_u];
            while(father_v != father[father_v]) father_v = father[father_v];
            int dest = min(father_u, father_v);
            father[father_u] = father[father_v] = dest;
        }
        int father_s = father[source] , father_d = father[destination];
        while(father_s != father[father_s]) father_s = father[father_s];
        while(father_d != father[father_d]) father_d = father[father_d];
        return father_d == father_s;
    }
};

class Solution {
public:
    long long countPairs(vector<int>& nums, int k) {
        map<int ,int> mp;
        long long cnt =0;
        for( int i =0;i<nums.size();i++){
            int x =  gcd(k,nums[i]);
            int req = k/x; 
            for( auto it: mp ){
                if( it.first % req == 0 ) cnt += it.second;
            }
            mp[x]++;
        }
        return cnt;
    }
};

class Solution {
public:
int mod = 1e9 +7;
    pair<long long,long long> fib(long long n){
        if( n == 0) return {0,1};

        auto [a,b] = fib(n/2);
        long long c = a*((2*b -a + mod)%mod ) % mod;
        long long d = (a*a % mod + b*b %mod)%mod;
        if(n%2 == 0){
            return {c,d};
        }
        else return {d, (c+d) % mod};
    }
    int countGoodStrings(long long n) {
        long long a = fib(n).first;
        a = (a*2)%mod;
        return a;
    }
};

class Solution {
public:
    vector<int> spiralOrder(vector<vector<int>>& matrix) {
        vector<int> v;
        int t=0,b=matrix.size()-1,
            l=0,r=matrix[0].size()-1;
        while(t <= b && l <= r){
        for( int i =l;i<=r;i++){
            v.push_back(matrix[t][i]);
        }
        t++;
        for( int i =t;i<=b;i++){
             v.push_back(matrix[i][r]);
        }
        r--;
        if(t<=b){
            for( int i =r;i>=l;i--){
             v.push_back(matrix[b][i]);
        }
        b--;}
        if(l<=r){
        for( int i =b;i>=t;i--){
             v.push_back(matrix[i][l]);
        }
        l++;
        }
        }
        return v;
    }
};

class Solution {
public:
    bool isRectangleCover(vector<vector<int>>& rectangles) {
        map<pair<int,int>,int>m;
        for( auto P : rectangles){
            m[{P[0],P[1]}]++;
            m[{P[2],P[3]}]++;
            m[{P[0],P[3]}]--;
            m[{P[2],P[1]}]--;
        }
        int sum = 0;
        for( auto it : m){
            sum += abs(it.second);
        }
        return sum == 4;
    }
};

class Solution {
public:
    ListNode* rotateRight(ListNode* head, int k) {
        if (!head || !head->next || k == 0)
            return head;
        int size = 1;

        ListNode* temp = head;

        while (temp->next) {
            size++;
            temp = temp->next;
        }
        k = k%size;
        if (k == 0) return head;
        temp->next = head;
        int s = size - k;
        ListNode* curr = head;

        while(--s){
            curr = curr->next;
        }

        ListNode* V = curr->next;
        curr->next = nullptr;

        return V;
    }
};

